def pause
  @subscription = Subscription.find(params[:subscription_id])
  @subscription.update!(paused_at: Time.current)
  redirect_to account_billing_path, notice: "Subscription paused"
end

def resume
  @subscription = current_user.subscriptions.find(params[:subscription_id])
  @subscription.update!(paused_at: nil)
  redirect_to account_billing_path, notice: "Subscription resumed"
end

