module Checkout
  class CompleteOrder
    def initialize(order)
      @order = order
    end

    def call
      ActiveRecord::Base.transaction do
        @order.update!(state: "paid", paid_at: Time.current)
        @order.line_items.each { |item| item.update!(fulfilled: false) }
        OrderMailer.confirmation(@order).deliver_now
      end
      @order
    end
  end
end

module Releases
  class ChangelogParser
    HEADING = /^## \[(\d+\.\d+\.\d+)\] - (\d{4}-\d{2}-\d{2})$/

    def initialize(markdown)
      @markdown = markdown
    end

    def versions
      @markdown.scan(HEADING).map { |version, date| { version: version, released_on: Date.parse(date) } }
    end
  end
end

