module Billing
  class PlanLookup
    def initialize(account)
      @account = account
    end

    def plan
      return @plan if defined?(@plan)

      @plan = Plan.find_by(code: @account.plan_code)
    end

    def client
      @client ||= Faraday.new(url: "https://billing.internal", request: { timeout: 5 })
    end
  end
end

class AccountSyncJob < ApplicationJob
  queue_as :default

  def perform(account_id)
    @account_id = account_id
    AccountSync.new(account).run
  end

  private

  def account
    @account ||= Account.find(@account_id)
  end

  def headers
    @headers ||= { "Authorization" => "Bearer #{account.sync_token}" }
  end
end

