class DigestMailer < ApplicationMailer
  def weekly(user)
    @user = user
    @highlights = user.feed_items.where(created_at: 1.week.ago..).order(score: :desc).limit(5)
    mail(to: user.email, subject: "Your week on Trailhead")
  end
end

class OrderSerializer
  def initialize(order)
    @order = order
  end

  def as_json(*)
    {
      id: @order.id,
      number: @order.number,
      total: Money.new(@order.total_cents, @order.currency).format,
      placed_at: @order.created_at.iso8601
    }
  end
end
